void MainWindow::updateSlaveEvidenceMatrix() {
  if (!slaveEvidenceMatrixTable_) {
    return;
  }

  int previousPosition = selectedPosition();
  if (slaveEvidenceMatrixTable_->currentRow() >= 0) {
    bool ok = false;
    const int rowPosition = tableText(slaveEvidenceMatrixTable_,
                                      slaveEvidenceMatrixTable_->currentRow(),
                                      kSlaveEvidenceMatrixPositionColumn)
                                .toInt(&ok);
    if (ok) {
      previousPosition = rowPosition;
    }
  }

  const SlaveEvidenceUiTexts uiTexts = slaveEvidenceUiTexts();

  QVector<SlaveEvidenceInput> evidenceInputs;
  evidenceInputs.reserve(slaves_.size());
  const QStringList topologyIssues = topologyBaselineIssues();
  const SlaveEvidenceLoadedPositions loadedPositions = {
      loadedSlaveInfoPosition_, identityTable_ ? identityTable_->rowCount() : 0,
      loadedSdoPosition_,       sdoTable_ ? sdoTable_->rowCount() : 0,
      loadedPdoPosition_,       pdoTable_ ? pdoTable_->rowCount() : 0,
  };
  const SlaveEvidenceLoadedTables loadedTables = {
      watchTable_,
      startupSdoTable_,
      freeRunEntryTable_,
  };

  for (const auto &slave : slaves_) {
    SlaveEvidenceInput input;
    input.position = slave.position;
    input.name = slave.name.trimmed();
    input.state = slave.state.trimmed();
    applyLoadedSlaveEvidence(&input, loadedPositions, loadedTables);
    input.topologyIssue = !topologyIssues.isEmpty();
    evidenceInputs.append(input);
  }

  const SlaveEvidenceMatrix evidenceMatrix =
      buildSlaveEvidenceMatrix(evidenceInputs);

  QList<QStringList> rows;
  for (const auto &row : evidenceMatrix.rows) {
    rows.append(slaveEvidenceUiRow(row, uiTexts).cells);
  }

  setTableRows(slaveEvidenceMatrixTable_, slaveEvidenceMatrixHeaders(uiTexts),
               rows);

  const QColor okColor("#22c55e");
  const QColor actionColor("#f59e0b");
  const QColor warningColor("#ef4444");
  const QColor infoColor("#60a5fa");
  int restoreRow = -1;
  for (int rowIndex = 0; rowIndex < slaveEvidenceMatrixTable_->rowCount();
       ++rowIndex) {
    bool ok = false;
    const int rowPosition = tableText(slaveEvidenceMatrixTable_, rowIndex,
                                      kSlaveEvidenceMatrixPositionColumn)
                                .toInt(&ok);
    if (ok && rowPosition == previousPosition) {
      restoreRow = rowIndex;
    }
    const auto evidence = evidenceMatrix.rows.value(rowIndex);
    const SlaveEvidenceUiRow uiRow = slaveEvidenceUiRow(evidence, uiTexts);
    setSlaveEvidenceMatrixRouteTarget(slaveEvidenceMatrixTable_, rowIndex,
                                      slaveEvidenceRouteTarget(evidence));
    const QColor readinessColor =
        evidence.risks.isEmpty() && evidence.readiness >= evidence.maxReadiness
            ? okColor
            : (!evidence.risks.isEmpty() ? warningColor : actionColor);
    const QString tooltip = uiRow.detailLines.join('\n');
    for (int column = 0; column < slaveEvidenceMatrixTable_->columnCount();
         ++column) {
      if (auto *item = slaveEvidenceMatrixTable_->item(rowIndex, column)) {
        item->setToolTip(tooltip);
      }
    }
    if (auto *item = slaveEvidenceMatrixTable_->item(
            rowIndex, kSlaveEvidenceMatrixPriorityColumn)) {
      const int priorityRank = slaveEvidencePriorityRank(evidence.priority);
      item->setForeground(priorityRank <= 1   ? warningColor
                          : priorityRank == 2 ? actionColor
                                              : okColor);
    }
    if (auto *item = slaveEvidenceMatrixTable_->item(
            rowIndex, kSlaveEvidenceMatrixStateColumn)) {
      const QString current = item->text().toUpper();
      item->setForeground(
          (current == "OP" || current.startsWith("OP ")) ? okColor
          : (current.contains("SAFEOP") || current.contains("PREOP"))
              ? actionColor
              : infoColor);
    }
    if (auto *item = slaveEvidenceMatrixTable_->item(
            rowIndex, kSlaveEvidenceMatrixReadinessColumn)) {
      item->setForeground(readinessColor);
    }
    for (int column : {5, 6, 7, 9}) {
      if (auto *item = slaveEvidenceMatrixTable_->item(rowIndex, column)) {
        const QString text = item->text().toLower();
        item->setForeground((text.contains("missing") || text.contains("缺失"))
                                ? warningColor
                                : okColor);
      }
    }
    if (auto *item = slaveEvidenceMatrixTable_->item(
            rowIndex, kSlaveEvidenceMatrixStartupColumn)) {
      item->setForeground(evidence.startupDiffs > 0 ? warningColor : okColor);
    }
    if (auto *item = slaveEvidenceMatrixTable_->item(
            rowIndex, kSlaveEvidenceMatrixRiskColumn)) {
      item->setForeground(evidence.risks.isEmpty() ? okColor : warningColor);
    }
    if (auto *item = slaveEvidenceMatrixTable_->item(
            rowIndex, kSlaveEvidenceMatrixNextColumn)) {
      item->setForeground(evidence.nextAction == SlaveEvidenceNextAction::Ready
                              ? okColor
                              : actionColor);
    }
  }

  if (restoreRow >= 0) {
    slaveEvidenceMatrixTable_->setCurrentCell(
        restoreRow, kSlaveEvidenceMatrixPositionColumn);
  }
  fitTableColumnsToViewport(slaveEvidenceMatrixTable_,
                            kSlaveEvidenceMatrixNextColumn);

  if (slaveEvidenceMatrixSummaryLabel_) {
    const QString summary =
        slaves_.isEmpty()
            ? uiText("No slaves in current scan", "当前扫描没有从站")
            : uiText("Priority queue | slaves %1 | ready %2 | action %3 | "
                     "risk %4 | evidence gaps %5",
                     "优先级队列 | 从站 %1 | 就绪 %2 | 待执行 %3 | 风险 %4 | "
                     "证据缺口 %5")
                  .arg(slaves_.size())
                  .arg(evidenceMatrix.readyRows)
                  .arg(evidenceMatrix.actionRows)
                  .arg(evidenceMatrix.riskRows)
                  .arg(evidenceMatrix.evidenceGaps);
    slaveEvidenceMatrixSummaryLabel_->setText(summary);
    slaveEvidenceMatrixSummaryLabel_->setToolTip(uiText(
        "This matrix is read-only and uses already loaded UI evidence only. "
        "Double-click or Alt+Enter selects the slave locally and routes to the "
        "best loaded evidence table without loading OD/PDO/ESI data from the "
        "bus.",
        "该矩阵只读且只使用已加载界面证据。双击或 Alt+Enter 会本地选择从站并"
        "路由到最相关的已加载证据表，不会从总线加载 OD/PDO/ESI 数据。"));
    slaveEvidenceMatrixSummaryLabel_->setProperty(
        "severity", evidenceMatrix.riskRows > 0
                        ? "warning"
                        : (evidenceMatrix.actionRows > 0 ? "action" : "ok"));
    repolish(slaveEvidenceMatrixSummaryLabel_);
  }
  filterSlaveEvidenceMatrix();
}

void MainWindow::filterSlaveEvidenceMatrix() {
  if (!slaveEvidenceMatrixTable_) {
    return;
  }

  const QString needle = slaveEvidenceMatrixFilter_
                             ? slaveEvidenceMatrixFilter_->text().trimmed()
                             : QString();
  const QString scope =
      slaveEvidenceMatrixScopeFilter_
          ? slaveEvidenceMatrixScopeFilter_->currentData().toString()
          : QString::fromLatin1(kSlaveEvidenceScopeAll);
  const SlaveEvidenceMatrixFilterStats stats =
      filterSlaveEvidenceMatrixTable(slaveEvidenceMatrixTable_, scope, needle);

  if (slaveEvidenceMatrixReviewButton_) {
    slaveEvidenceMatrixReviewButton_->setEnabled(stats.hasVisibleIssue);
  }
  if (slaveEvidenceMatrixReviewNextButton_) {
    slaveEvidenceMatrixReviewNextButton_->setEnabled(stats.hasVisibleIssue);
  }
  if (slaveEvidenceMatrixCopyButton_) {
    const int current = slaveEvidenceMatrixTable_->currentRow();
    slaveEvidenceMatrixCopyButton_->setEnabled(
        current >= 0 && current < slaveEvidenceMatrixTable_->rowCount() &&
        !slaveEvidenceMatrixTable_->isRowHidden(current));
  }

  if (slaveEvidenceMatrixSummaryLabel_) {
    const QString scopeLabel =
        slaveEvidenceMatrixScopeFilter_
            ? slaveEvidenceMatrixScopeFilter_->currentText()
            : uiText("All", "全部");
    slaveEvidenceMatrixSummaryLabel_->setToolTip(
        uiText("Visible matrix rows: %1/%2\nScope: %3\nPriority: P0 %4 | P1 "
               "%5 | P2 %6 | P3 %7\nRisk: %8 | Action: %9 | Ready: "
               "%10\nFiltering is local only and does not read the bus.",
               "可见矩阵行：%1/%2\n范围：%3\n优先级：P0 %4 | P1 %5 | P2 %6 | "
               "P3 %7\n风险：%8 | 待执行：%9 | 就绪：%10\n过滤仅在本地完成，不"
               "读取总线。")
            .arg(stats.visible)
            .arg(slaveEvidenceMatrixTable_->rowCount())
            .arg(scopeLabel)
            .arg(stats.p0)
            .arg(stats.p1)
            .arg(stats.p2)
            .arg(stats.p3)
            .arg(stats.risk)
            .arg(stats.action)
            .arg(stats.ready));
  }
  updateSlaveEvidenceMatrixTriageButtons();
  updateTabBadges();
  updateWorkspaceBoundary();
}

void MainWindow::updateSlaveEvidenceMatrixTriageButtons() {
  if (slaveEvidenceMatrixTriageButtons_.isEmpty()) {
    return;
  }
  const SlaveEvidenceMatrixPriorityCounts priorityCounts =
      slaveEvidenceMatrixPriorityCounts(slaveEvidenceMatrixTable_);
  const QHash<QString, int> counts = {
      {QString::fromLatin1(kSlaveEvidenceScopePriorityP0), priorityCounts.p0},
      {QString::fromLatin1(kSlaveEvidenceScopePriorityP1), priorityCounts.p1},
      {QString::fromLatin1(kSlaveEvidenceScopePriorityP2), priorityCounts.p2},
      {QString::fromLatin1(kSlaveEvidenceScopePriorityP3), priorityCounts.p3},
  };
  const QHash<QString, QString> labels = {
      {QString::fromLatin1(kSlaveEvidenceScopePriorityP0), uiText("P0", "P0")},
      {QString::fromLatin1(kSlaveEvidenceScopePriorityP1), uiText("P1", "P1")},
      {QString::fromLatin1(kSlaveEvidenceScopePriorityP2), uiText("P2", "P2")},
      {QString::fromLatin1(kSlaveEvidenceScopePriorityP3), uiText("P3", "P3")},
  };
  const QString currentScope =
      slaveEvidenceMatrixScopeFilter_
          ? slaveEvidenceMatrixScopeFilter_->currentData().toString()
          : QString();
  for (auto *button : slaveEvidenceMatrixTriageButtons_) {
    if (!button) {
      continue;
    }
    const QString scope = button->property("scope").toString();
    const int count = counts.value(scope, 0);
    button->setText(
        QString("%1 %2").arg(labels.value(scope, scope)).arg(count));
    button->setCheckable(true);
    button->setChecked(scope == currentScope);
    button->setEnabled(slaveEvidenceMatrixTable_ &&
                       slaveEvidenceMatrixTable_->rowCount() > 0);
    button->setToolTip(
        uiText("Show %1 matrix rows. Count: %2. This is local UI filtering "
               "only and does not read the bus.",
               "显示 %1 矩阵行。数量：%2。这只是本地界面过滤，不读取总线。")
            .arg(labels.value(scope, scope))
            .arg(count));
  }
}

void MainWindow::reviewFirstSlaveEvidenceMatrixIssue() {
  if (!slaveEvidenceMatrixTable_) {
    return;
  }
  filterSlaveEvidenceMatrix();
  int fallbackRow = -1;
  for (int row = 0; row < slaveEvidenceMatrixTable_->rowCount(); ++row) {
    if (slaveEvidenceMatrixTable_->isRowHidden(row)) {
      continue;
    }
    const SlaveEvidenceMatrixRowState state =
        slaveEvidenceMatrixRowState(slaveEvidenceMatrixTable_, row);
    if (!state.reviewIssue) {
      continue;
    }
    if (state.hasRisk) {
      openSlaveEvidenceMatrixRow(row);
      return;
    }
    if (fallbackRow < 0) {
      fallbackRow = row;
    }
  }
  if (fallbackRow >= 0) {
    openSlaveEvidenceMatrixRow(fallbackRow);
    return;
  }
  statusBar()->showMessage(uiText("No visible matrix issue to review.",
                                  "当前没有可见的矩阵问题可审阅。"),
                           3000);
}

void MainWindow::reviewNextSlaveEvidenceMatrixIssue() {
  if (!slaveEvidenceMatrixTable_) {
    return;
  }
  filterSlaveEvidenceMatrix();
  const int rowCount = slaveEvidenceMatrixTable_->rowCount();
  if (rowCount <= 0) {
    statusBar()->showMessage(
        uiText("No matrix issue to review.", "当前没有矩阵问题可审阅。"), 3000);
    return;
  }

  auto isIssueRow = [this](int row) {
    if (row < 0 || row >= slaveEvidenceMatrixTable_->rowCount() ||
        slaveEvidenceMatrixTable_->isRowHidden(row)) {
      return false;
    }
    return slaveEvidenceMatrixRowState(slaveEvidenceMatrixTable_, row)
        .reviewIssue;
  };

  const int current = slaveEvidenceMatrixTable_->currentRow();
  for (int offset = 1; offset <= rowCount; ++offset) {
    const int row = (qMax(0, current) + offset) % rowCount;
    if (isIssueRow(row)) {
      openSlaveEvidenceMatrixRow(row);
      return;
    }
  }

  statusBar()->showMessage(uiText("No visible matrix issue to review.",
                                  "当前没有可见的矩阵问题可审阅。"),
                           3000);
}

bool MainWindow::copySlaveEvidenceMatrixRowDigest(int row) {
  if (!slaveEvidenceMatrixTable_ || row < 0 ||
      row >= slaveEvidenceMatrixTable_->rowCount() ||
      slaveEvidenceMatrixTable_->isRowHidden(row)) {
    statusBar()->showMessage(
        uiText("Select a visible slave evidence matrix row to copy.",
               "请选择一条可见的从站证据矩阵行再复制。"),
        3000);
    return false;
  }

  QStringList lines;
  lines << uiText("NekoEcat Studio Slave Evidence Matrix Row",
                  "NekoEcat Studio 从站证据矩阵本行");
  lines << QString("%1: %2").arg(uiText("Master", "主站"), activeMasterName());
  if (slaveEvidenceMatrixScopeFilter_) {
    lines << QString("%1: %2").arg(
        uiText("Matrix Scope", "矩阵范围"),
        slaveEvidenceMatrixScopeFilter_->currentText());
  }
  if (slaveEvidenceMatrixFilter_ &&
      !slaveEvidenceMatrixFilter_->text().trimmed().isEmpty()) {
    lines << QString("%1: %2").arg(
        uiText("Search", "搜索"), slaveEvidenceMatrixFilter_->text().trimmed());
  }
  if (slaveEvidenceMatrixSummaryLabel_ &&
      !slaveEvidenceMatrixSummaryLabel_->text().trimmed().isEmpty()) {
    lines << QString("%1: %2").arg(
        uiText("Matrix Summary", "矩阵摘要"),
        slaveEvidenceMatrixSummaryLabel_->text().trimmed());
  }

  lines << QString();
  lines << uiText("Row Evidence", "本行证据");
  for (int column = 0; column < slaveEvidenceMatrixTable_->columnCount();
       ++column) {
    const auto *header =
        slaveEvidenceMatrixTable_->horizontalHeaderItem(column);
    const QString field =
        header ? header->text().trimmed() : QString::number(column + 1);
    const QString value = tableText(slaveEvidenceMatrixTable_, row, column);
    lines << QString("- %1: %2")
                 .arg(field, value.isEmpty() ? uiText("Empty", "空") : value);
  }

  QString details;
  for (int column = 0; column < slaveEvidenceMatrixTable_->columnCount();
       ++column) {
    if (auto *item = slaveEvidenceMatrixTable_->item(row, column)) {
      details = item->toolTip().trimmed();
      if (!details.isEmpty()) {
        break;
      }
    }
  }
  if (!details.isEmpty()) {
    lines << QString();
    lines << uiText("Detailed Evidence", "详细证据");
    const QStringList detailLines = details.split('\n', Qt::SkipEmptyParts);
    for (const QString &detail : detailLines) {
      lines << QString("- %1").arg(detail.trimmed());
    }
  }

  lines << QString();
  lines << uiText("Local Action: Open Matrix Evidence routes this slave to the "
                  "best already loaded evidence table; Review First/Next walks "
                  "visible matrix issues.",
                  "本地动作：打开矩阵证据会把该从站路由到最相关的已加载证据表；"
                  "审阅首个/下个问题会遍历可见矩阵问题。");
  lines << uiText("Boundary: clipboard copy only; no bus read, no OD/PDO/ESI "
                  "load, no SDO write, no state change, no Free Run change, "
                  "and no Host Health.",
                  "边界：只复制到剪贴板；不读取总线、不加载 OD/PDO/ESI、不写 "
                  "SDO、不切换状态、不改变 Free Run，也不运行 Host Health。");

  QApplication::clipboard()->setText(lines.join('\n'));
  updateDiagnostics("Info", "Slave Evidence Matrix",
                    uiText("Copied slave evidence matrix row #%1 to clipboard",
                           "已复制从站证据矩阵第 %1 行到剪贴板")
                        .arg(row + 1));
  statusBar()->showMessage(
      uiText("Copied slave evidence matrix row. No bus access was requested.",
             "已复制从站证据矩阵行；未请求总线访问。"),
      3000);
  return true;
}

void MainWindow::openSlaveEvidenceMatrixRow(int row) {
  if (!slaveEvidenceMatrixTable_ || row < 0 ||
      row >= slaveEvidenceMatrixTable_->rowCount()) {
    statusBar()->showMessage(uiText("Select a slave evidence row first.",
                                    "请先选择一条从站证据矩阵行。"),
                             3000);
    return;
  }

  bool ok = false;
  const int position = tableText(slaveEvidenceMatrixTable_, row,
                                 kSlaveEvidenceMatrixPositionColumn)
                           .toInt(&ok);
  if (!ok || position < 0) {
    return;
  }

  if (!selectSlaveForLocalEvidence(position)) {
    statusBar()->showMessage(
        uiText("Slave is not present in the local topology tree.",
               "本地拓扑树中没有该从站。"),
        3000);
    return;
  }

  selectAndFocusTableRow(slaveEvidenceMatrixTable_, row,
                         kSlaveEvidenceMatrixPositionColumn);

  QString target = uiText("Overview matrix row", "总览矩阵行");
  bool routed = false;
  switch (
      slaveEvidenceMatrixRouteTargetForRow(slaveEvidenceMatrixTable_, row)) {
  case SlaveEvidenceRouteTarget::ObjectDictionary:
    activateObjectDictionaryPaneFor(sdoTable_);
    if (loadedSdoPosition_ == position && sdoTable_ &&
        sdoTable_->rowCount() > 0) {
      selectAndFocusTableRow(
          sdoTable_, sdoTable_->currentRow() >= 0 ? sdoTable_->currentRow() : 0,
          0);
    }
    target = uiText("Object Dictionary evidence", "对象字典证据");
    routed = true;
    break;
  case SlaveEvidenceRouteTarget::PdoMap:
    activateWorkspaceTab(pdoMapTabIndex_);
    if (loadedPdoPosition_ == position && pdoTable_ &&
        pdoTable_->rowCount() > 0) {
      selectAndFocusTableRow(
          pdoTable_, pdoTable_->currentRow() >= 0 ? pdoTable_->currentRow() : 0,
          0);
    }
    target = uiText("PDO Map evidence", "PDO 映射证据");
    routed = true;
    break;
  case SlaveEvidenceRouteTarget::Watch: {
    const int watchRow = firstSlaveEvidenceDriveWatchRow(watchTable_, position);
    activateWorkspaceTab(watchTabIndex_);
    if (watchScopeFilter_) {
      const int scope = watchScopeFilter_->findData("all");
      if (scope >= 0) {
        watchScopeFilter_->setCurrentIndex(scope);
      }
    }
    if (watchChangedOnly_) {
      watchChangedOnly_->setChecked(false);
    }
    filterWatchTable();
    if (watchRow >= 0) {
      selectAndFocusTableRow(watchTable_, watchRow,
                             kSlaveEvidenceWatchPositionColumn);
    } else {
      const int anyWatchRow = firstSlaveEvidenceRowForPosition(
          watchTable_, position, kSlaveEvidenceWatchPositionColumn);
      if (anyWatchRow >= 0) {
        selectAndFocusTableRow(watchTable_, anyWatchRow,
                               kSlaveEvidenceWatchPositionColumn);
      }
    }
    target = uiText("Watch evidence", "Watch 证据");
    routed = true;
    break;
  }
  case SlaveEvidenceRouteTarget::Startup: {
    updateStartupSdoWatchEvidence();
    const int startupRow =
        firstSlaveEvidenceStartupDiffRow(startupSdoTable_, position);
    activateWorkspaceTab(startupSdoTabIndex_);
    if (startupWatchDiffsOnly_) {
      startupWatchDiffsOnly_->setChecked(false);
    }
    filterStartupSdoTable();
    if (startupRow >= 0) {
      selectAndFocusTableRow(startupSdoTable_, startupRow,
                             kSlaveEvidenceStartupPositionColumn);
    }
    updateStartupSdoControls();
    target = uiText("Startup SDO evidence", "Startup SDO 证据");
    routed = true;
    break;
  }
  case SlaveEvidenceRouteTarget::Process: {
    const int processRow =
        firstSlaveEvidenceProcessIssueRow(freeRunEntryTable_, position);
    activateWorkspaceTab(freeRunTabIndex_);
    filterFreeRunEntryTable();
    if (processRow >= 0) {
      selectAndFocusTableRow(freeRunEntryTable_, processRow,
                             kSlaveEvidenceProcessPositionColumn);
    } else {
      const int anyProcessRow = firstSlaveEvidenceRowForPosition(
          freeRunEntryTable_, position, kSlaveEvidenceProcessPositionColumn);
      if (anyProcessRow >= 0) {
        selectAndFocusTableRow(freeRunEntryTable_, anyProcessRow,
                               kSlaveEvidenceProcessPositionColumn);
      }
    }
    target = uiText("Free Run process evidence", "Free Run 过程证据");
    routed = true;
    break;
  }
  case SlaveEvidenceRouteTarget::StateMachine: {
    updateStateMachineView();
    activateWorkspaceTab(stateMachineTabIndex_);
    const int stateRow =
        firstSlaveEvidenceRowForPosition(stateMachineTable_, position, 0);
    if (stateRow >= 0) {
      selectAndFocusTableRow(stateMachineTable_, stateRow, 0);
    }
    target = uiText("State Machine risk evidence", "状态机风险证据");
    routed = true;
    break;
  }
  case SlaveEvidenceRouteTarget::Overview:
    break;
  }

  if (!routed) {
    activateWorkspaceTab(overviewTabIndex_);
  }
  updateDiagnostics(
      "Info", "Slave Evidence Matrix",
      uiText("Opened %1 for slave #%2 from the read-only evidence matrix "
             "without bus access.",
             "已从只读证据矩阵为从站 #%2 打开 %1，未访问总线。")
          .arg(target)
          .arg(position));
  statusBar()->showMessage(
      uiText("Local slave evidence opened. No bus access was requested.",
             "已打开本地从站证据；未请求总线访问。"),
      3000);
}

int MainWindow::slaveEvidenceMatrixRowForPosition(int position) const {
  return firstSlaveEvidenceRowForPosition(slaveEvidenceMatrixTable_, position,
                                          kSlaveEvidenceMatrixPositionColumn);
}

void MainWindow::updateSessionBrief() {
  if (!sessionBriefTable_) {
    return;
  }

  const bool connected = client_.isConnected();
  const bool hasSlaves = !slaves_.isEmpty();
  const int selected = selectedPosition();
  const bool hasSelectedSlave = selected >= 0;
  const bool hasSdoRows = hasSelectedSlave && loadedSdoPosition_ == selected &&
                          sdoTable_ && sdoTable_->rowCount() > 0;
  const bool hasPdoRows = hasSelectedSlave && loadedPdoPosition_ == selected &&
                          pdoTable_ && pdoTable_->rowCount() > 0;
  const bool hasWatchRows = watchTable_ && watchTable_->rowCount() > 0;
  const bool hasFreeRunRows =
      freeRunEntryTable_ && freeRunEntryTable_->rowCount() > 0;
  const bool hasFailedOdEvidence = hasFailedSdoEvidence();
  const int startupDiffs = startupSdoRowsWithWatchDiffs().size();

  QString selectedSlave = uiText("No selected slave", "未选择从站");
  QString selectedState = uiText("none", "无");
  if (hasSelectedSlave) {
    selectedSlave = QString("#%1").arg(selected);
    for (const auto &slave : slaves_) {
      if (slave.position == selected) {
        const QString name = slave.name.trimmed();
        selectedSlave = name.isEmpty()
                            ? selectedSlave
                            : QString("#%1 %2").arg(selected).arg(name);
        selectedState = slave.state.trimmed().isEmpty()
                            ? uiText("unknown", "未知")
                            : slave.state.trimmed();
        break;
      }
    }
  }

  SessionBriefInput briefInput;
  briefInput.connected = connected;
  briefInput.hasSlaves = hasSlaves;
  briefInput.hasSelectedSlave = hasSelectedSlave;
  briefInput.hasSdoRows = hasSdoRows;
  briefInput.hasPdoRows = hasPdoRows;
  briefInput.hasFailedOdEvidence = hasFailedOdEvidence;
  briefInput.hasWatchRows = hasWatchRows;
  briefInput.freeRunEnabled = freeRun_;
  briefInput.hasFreeRunRows = hasFreeRunRows;
  briefInput.startupDiffs = startupDiffs;

  int consistencyErrors = 0;
  int consistencyWarnings = 0;
  int consistencyInfos = 0;
  int consistencyReady = 0;
  consistencyIssueCounts(&consistencyErrors, &consistencyWarnings,
                         &consistencyInfos, &consistencyReady);
  const bool hasConsistencyCheck =
      consistencyFresh_ && consistencyCheckAvailable();
  const bool hasConsistencyBlockingIssues =
      consistencyHasBlockingIssues({consistencyErrors, consistencyWarnings,
                                    consistencyInfos, consistencyReady});
  briefInput.hasConsistencyCheck = hasConsistencyCheck;
  briefInput.consistencyErrors = consistencyErrors;
  briefInput.consistencyWarnings = consistencyWarnings;

  QString sdoEvidenceText =
      uiText("No complete SDO target", "尚无完整 SDO 目标");
  QString sdoNext = uiText("Select an OD row or fill SDO fields",
                           "选择 OD 行或填写 SDO 字段");
  if (hasSelectedSlave && sdoIndex_ && sdoSubIndex_ &&
      !sdoIndex_->text().trimmed().isEmpty() &&
      !sdoSubIndex_->text().trimmed().isEmpty()) {
    briefInput.currentSdoComplete = true;
    const QString address =
        QString("%1:%2").arg(normalizeHexText(sdoIndex_->text(), 4),
                             normalizeHexText(sdoSubIndex_->text(), 2));
    const auto candidates = currentSdoEvidenceCandidates();
    QStringList facts;
    QStringList groups;
    for (const auto &candidate : candidates) {
      const QString normalized = normalizeComparableValue(candidate.second);
      if (normalized.isEmpty()) {
        continue;
      }
      bool seen = false;
      const auto &existingGroups = groups;
      for (const QString &group : existingGroups) {
        if (group == normalized) {
          seen = true;
          break;
        }
      }
      if (!seen) {
        groups << normalized;
      }
      facts << QString("%1=%2").arg(candidate.first, candidate.second);
    }

    const QString writeValue =
        sdoWriteValue_ ? sdoWriteValue_->text().trimmed() : QString();
    bool writeDiffers = false;
    bool writeMatches = false;
    if (!writeValue.isEmpty() && !groups.isEmpty()) {
      const QString normalizedWrite = normalizeComparableValue(writeValue);
      const auto &existingGroups = groups;
      for (const QString &group : existingGroups) {
        if (group == normalizedWrite) {
          writeMatches = true;
        } else {
          writeDiffers = true;
        }
      }
    }
    briefInput.currentSdoEvidenceGroups = groups.size();
    briefInput.currentSdoHasEvidence = !candidates.isEmpty();
    briefInput.currentSdoWriteDiffers = writeDiffers;
    briefInput.currentSdoWriteMatches = writeMatches;

    if (groups.size() > 1) {
      sdoNext =
          uiText("Review evidence delta before writing", "写入前审阅证据差异");
    } else if (writeDiffers && !writeMatches) {
      sdoNext = uiText("Confirm write delta", "确认写入差异");
    } else if (!candidates.isEmpty()) {
      sdoNext =
          writeValue.isEmpty()
              ? uiText("Use evidence or read target", "使用证据或读取目标")
              : uiText("Write uses normal confirmation", "写入走普通确认流程");
    } else {
      sdoNext = uiText("Read target or add Watch evidence",
                       "读取目标或添加 Watch 证据");
    }
    sdoEvidenceText =
        uiText("%1 | evidence %2 group(s)%3", "%1 | 证据 %2 组%3")
            .arg(address)
            .arg(groups.size())
            .arg(facts.isEmpty() ? QString()
                                 : QString(" | %1").arg(facts.join("; ")));
    if (!writeValue.isEmpty()) {
      sdoEvidenceText += uiText(" | write %1", " | 写入 %1").arg(writeValue);
    }
  }

  QString nextAction = uiText("Open command palette", "打开命令面板");
  const int nextStep = nextCommissioningWorkflowStep();
  briefInput.nextWorkflowStep = nextStep;
  if (nextStep >= 0 && workflowTable_ &&
      nextStep < workflowTable_->rowCount()) {
    nextAction =
        commissioningWorkflowTableRowFromTable(workflowTable_, nextStep)
            .nextAction;
  } else if (nextBestActionButton_) {
    nextAction = nextBestActionButton_->text();
  }

  const QVector<SessionBriefRow> briefRows = buildSessionBriefRows(briefInput);
  const SessionBriefUiTexts uiTexts = sessionBriefUiTexts();
  QList<SessionBriefUiRow> rows;
  rows.reserve(briefRows.size());
  rows.append(sessionBriefUiRow(
      briefRows.at(0), uiText("Target", "目标"),
      uiText("%1 | runtime %2 | %3 slave(s)", "%1 | 运行时 %2 | %3 个从站")
          .arg(selectedSlave, connected ? uiText("connected", "已连接")
                                        : uiText("offline", "离线"))
          .arg(slaves_.size()),
      !connected ? uiText("Connect runtime", "连接运行时")
                 : (!hasSlaves ? uiText("Rescan bus", "重新扫描总线")
                               : (!hasSelectedSlave
                                      ? uiText("Select a slave", "选择从站")
                                      : uiText("Continue evidence review",
                                               "继续证据复核"))),
      uiTexts));
  rows.append(sessionBriefUiRow(
      briefRows.at(1), uiText("Gate", "门禁"),
      hasConsistencyCheck
          ? uiText("Consistency: %1 error(s), %2 warning(s), %3 info, %4 "
                   "ready",
                   "一致性：%1 错误，%2 警告，%3 信息，%4 就绪")
                .arg(consistencyErrors)
                .arg(consistencyWarnings)
                .arg(consistencyInfos)
                .arg(consistencyReady)
          : uiText("Consistency check is not fresh", "一致性检查尚未刷新"),
      hasConsistencyCheck && hasConsistencyBlockingIssues
          ? uiText("Open blocking evidence", "打开阻塞证据")
          : (hasConsistencyCheck
                 ? uiText("Proceed when machine is safe", "设备安全时继续")
                 : uiText("Run read-only consistency gate",
                          "运行只读一致性门禁")),
      uiTexts));
  rows.append(sessionBriefUiRow(
      briefRows.at(2), uiText("Map", "映射"),
      uiText("OD %1 row(s) | PDO %2 row(s) | failed OD %3",
             "OD %1 行 | PDO %2 行 | 失败 OD %3")
          .arg(sdoTable_ ? sdoTable_->rowCount() : 0)
          .arg(pdoTable_ ? pdoTable_->rowCount() : 0)
          .arg(hasFailedOdEvidence ? uiText("yes", "有") : uiText("no", "无")),
      !hasSelectedSlave
          ? uiText("Select slave", "选择从站")
          : (!hasSdoRows
                 ? uiText("Load Object Dictionary", "加载对象字典")
                 : (!hasPdoRows ? uiText("Load PDO Map", "加载 PDO 映射")
                                : (hasFailedOdEvidence
                                       ? uiText("Review failed OD evidence",
                                                "审阅失败 OD 证据")
                                       : uiText("Map evidence ready",
                                                "映射证据就绪")))),
      uiTexts));
  rows.append(sessionBriefUiRow(briefRows.at(3),
                                uiText("Current SDO", "当前 SDO"),
                                sdoEvidenceText, sdoNext, uiTexts));
  rows.append(sessionBriefUiRow(
      briefRows.at(4), uiText("Runtime Evidence", "运行证据"),
      uiText("Watch %1 row(s) | Startup diff %2 | Free Run %3 | process %4",
             "Watch %1 行 | Startup 偏差 %2 | Free Run %3 | 过程项 %4")
          .arg(watchTable_ ? watchTable_->rowCount() : 0)
          .arg(startupDiffs)
          .arg(freeRun_ ? uiText("on", "开启") : uiText("off", "关闭"))
          .arg(freeRunEntryTable_ ? freeRunEntryTable_->rowCount() : 0),
      startupDiffs > 0
          ? uiText("Review Startup diffs", "审阅 Startup 偏差")
          : (!hasWatchRows
                 ? uiText("Add Watch evidence", "添加 Watch 证据")
                 : (!freeRun_ && !hasFreeRunRows
                        ? uiText("Validate process image when safe",
                                 "安全时验证过程映像")
                        : uiText("Runtime evidence ready", "运行证据就绪"))),
      uiTexts));
  rows.append(sessionBriefUiRow(
      briefRows.at(5), uiText("Next", "下一步"),
      uiText("State %1 | workflow row %2", "状态 %1 | 工作流行 %2")
          .arg(selectedState)
          .arg(nextStep >= 0 ? QString::number(nextStep + 1)
                             : uiText("ready", "就绪")),
      nextAction, uiTexts));

  QList<QStringList> tableRows;
  for (const auto &row : rows) {
    tableRows.append(row.cells);
  }
  setTableRows(sessionBriefTable_, sessionBriefTableHeaders(uiTexts),
               tableRows);

  const QColor readyColor("#22c55e");
  const QColor actionColor("#f59e0b");
  const QColor warningColor("#f59e0b");
  const QColor errorColor("#ef4444");
  for (int row = 0; row < sessionBriefTable_->rowCount(); ++row) {
    const SessionBriefUiRow uiRow = rows.value(row);
    const QString colorKey = sessionBriefStatusColorKey(uiRow.status);
    const QColor color =
        colorKey == QStringLiteral("ready")
            ? readyColor
            : (colorKey == QStringLiteral("error")
                   ? errorColor
                   : (colorKey == QStringLiteral("warning") ? warningColor
                                                            : actionColor));
    for (int column = 0; column < sessionBriefTable_->columnCount(); ++column) {
      if (auto *item = sessionBriefTable_->item(row, column)) {
        item->setForeground(color);
        item->setToolTip(uiRow.tooltips.value(column));
      }
    }
    setSessionBriefActionKey(sessionBriefTable_, row, uiRow.actionKey);
  }
  fitTableColumnsToViewport(sessionBriefTable_, kSessionBriefEvidenceColumn);
  updateSessionBriefCopyButton();
}

void MainWindow::updateSessionBriefCopyButton() {
  if (!sessionBriefCopyButton_ || !sessionBriefTable_) {
    return;
  }
  const int row = sessionBriefTable_->currentRow();
  const bool hasRow = row >= 0 && row < sessionBriefTable_->rowCount();
  sessionBriefCopyButton_->setEnabled(hasRow);
  if (!hasRow) {
    sessionBriefCopyButton_->setText(uiText("Copy Row", "复制本行"));
    sessionBriefCopyButton_->setToolTip(uiText(
        "Select a Session Brief row to copy its local evidence summary. No "
        "bus request is sent.",
        "选择一条会话简报行以复制本地证据摘要；不会发送总线请求。"));
    return;
  }

  const QString area =
      sessionBriefTableRowFromTable(sessionBriefTable_, row).area.trimmed();
  sessionBriefCopyButton_->setText(
      area.isEmpty() ? uiText("Copy Row", "复制本行")
                     : uiText("Copy: %1", "复制：%1").arg(area));
  sessionBriefCopyButton_->setToolTip(
      uiText("Copy the Session Brief row \"%1\" with status, evidence, next "
             "action, and local boundary. Clipboard only; no bus access.",
             "复制会话简报行“%1”的状态、依据、下一步和本地边界。只写剪贴板；"
             "不访问总线。")
          .arg(area.isEmpty() ? uiText("selected row", "所选行") : area));
}

bool MainWindow::copySessionBriefRowDigest(int row) {
  if (!sessionBriefTable_ || row < 0 || row >= sessionBriefTable_->rowCount()) {
    statusBar()->showMessage(uiText("Select a Session Brief row to copy.",
                                    "请选择一条会话简报行再复制。"),
                             3000);
    return false;
  }

  const SessionBriefTableRow briefRow =
      sessionBriefTableRowFromTable(sessionBriefTable_, row);

  QStringList lines;
  lines << uiText("NekoEcat Studio Session Brief Row",
                  "NekoEcat Studio 会话简报本行");
  lines << QString("%1: %2").arg(uiText("Master", "主站"), activeMasterName());
  lines << QString("%1: %2").arg(uiText("Area", "区域"), briefRow.area);
  lines << QString("%1: %2").arg(uiText("Status", "状态"), briefRow.status);
  lines << QString("%1: %2").arg(uiText("Evidence", "依据"), briefRow.evidence);
  lines << QString("%1: %2").arg(uiText("Next", "下一步"), briefRow.next);
  if (!briefRow.actionKey.isEmpty()) {
    lines << QString("%1: %2").arg(uiText("Local Route", "本地路由"),
                                   briefRow.actionKey);
  }
  if (nextBestActionButton_) {
    lines << QString("%1: %2").arg(
        uiText("Current Next Best Action", "当前下一最佳动作"),
        nextBestActionButton_->text().trimmed());
  }
  if (!briefRow.firstTooltip.isEmpty()) {
    lines << QString();
    lines << uiText("Row Detail", "行详情");
    const QStringList detailLines =
        briefRow.firstTooltip.split('\n', Qt::SkipEmptyParts);
    for (const QString &detail : detailLines) {
      lines << QString("- %1").arg(detail.trimmed());
    }
  }

  lines << QString();
  lines << uiText(
      "Local Action: Open Session Brief Evidence routes this row "
      "to the already loaded local evidence surface.",
      "本地动作：打开会话简报证据会把该行路由到已加载的本地证据界面。");
  lines << uiText("Boundary: clipboard copy only; no bus read, no OD/PDO/ESI "
                  "load, no SDO write, no state change, no Free Run change, "
                  "and no Host Health.",
                  "边界：只复制到剪贴板；不读取总线、不加载 OD/PDO/ESI、不写 "
                  "SDO、不切换状态、不改变 Free Run，也不运行 Host Health。");

  QApplication::clipboard()->setText(lines.join('\n'));
  updateDiagnostics("Info", "Session Brief",
                    uiText("Copied Session Brief row #%1 to clipboard",
                           "已复制会话简报第 %1 行到剪贴板")
                        .arg(row + 1));
  statusBar()->showMessage(
      uiText("Copied Session Brief row. No bus access was requested.",
             "已复制会话简报行；未请求总线访问。"),
      3000);
  return true;
}

void MainWindow::updateWorkflowStepCopyButton() {
  if (!workflowStepCopyButton_ || !workflowTable_) {
    return;
  }
  const int row = workflowTable_->currentRow();
  const bool hasRow = row >= 0 && row < workflowTable_->rowCount() &&
                      !workflowTable_->isRowHidden(row);
  workflowStepCopyButton_->setEnabled(hasRow);
  if (!hasRow) {
    workflowStepCopyButton_->setText(uiText("Copy Step", "复制步骤"));
    workflowStepCopyButton_->setToolTip(uiText(
        "Select a commissioning workflow step to copy its local evidence "
        "summary. No bus request is sent.",
        "选择一条调试工作流步骤以复制本地证据摘要；不会发送总线请求。"));
    return;
  }

  const QString step =
      commissioningWorkflowTableRowFromTable(workflowTable_, row)
          .step.trimmed();
  workflowStepCopyButton_->setText(
      step.isEmpty() ? uiText("Copy Step", "复制步骤")
                     : uiText("Copy: %1", "复制：%1").arg(step));
  workflowStepCopyButton_->setToolTip(
      uiText("Copy workflow step \"%1\" with phase, status, risk, evidence, "
             "next action, tooltip detail, and local boundary. Clipboard "
             "only; no bus access.",
             "复制工作流步骤“%1”的阶段、状态、风险、依据、下一步、提示详情和"
             "本地边界。只写剪贴板；不访问总线。")
          .arg(step.isEmpty() ? uiText("selected step", "所选步骤") : step));
}

void MainWindow::updateWorkflowStepDetail() {
  if (!workflowStepDetailLabel_) {
    return;
  }
  const CommissioningWorkflowStepDetailTexts texts =
      commissioningWorkflowStepDetailTexts();
  auto applyState =
      [this](const CommissioningWorkflowStepDetailUiState &state) {
        workflowStepDetailLabel_->setText(state.text);
        workflowStepDetailLabel_->setProperty("severity", state.severityKey);
        workflowStepDetailLabel_->setToolTip(state.tooltip);
        repolish(workflowStepDetailLabel_);
      };

  if (!workflowTable_) {
    applyState(commissioningWorkflowStepDetailUnavailableState(texts));
    return;
  }

  const int row = workflowTable_->currentRow();
  if (row < 0 || row >= workflowTable_->rowCount() ||
      workflowTable_->isRowHidden(row)) {
    applyState(commissioningWorkflowStepDetailNoSelectionState(texts));
    return;
  }

  applyState(buildCommissioningWorkflowStepDetailUiState(
      commissioningWorkflowTableRowFromTable(workflowTable_, row),
      commissioningWorkflowTexts(), texts));
}

void MainWindow::openSessionBriefRow(int row) {
  if (!sessionBriefTable_) {
    return;
  }
  if (row < 0 || row >= sessionBriefTable_->rowCount()) {
    row = sessionBriefTable_->currentRow();
  }
  if (row < 0 || row >= sessionBriefTable_->rowCount()) {
    return;
  }

  const SessionBriefTableRow briefRow =
      sessionBriefTableRowFromTable(sessionBriefTable_, row);
  QString actionKey = briefRow.actionKey;
  const QString area = briefRow.area.toLower();
  const QString status = briefRow.status.toLower();
  const QString evidence = briefRow.evidence.toLower();
  const QString next = briefRow.next.toLower();
  const QString combined =
      QString("%1 %2 %3 %4").arg(area, status, evidence, next);

  auto logNavigation = [this](const QString &target) {
    updateDiagnostics("Info", "Session Brief",
                      uiText("Opened local Session Brief evidence: %1",
                             "已打开会话简报本地证据：%1")
                          .arg(target));
  };

  if (actionKey.isEmpty()) {
    if (area == uiText("Target", "目标").toLower()) {
      actionKey = QStringLiteral("target");
    } else if (area == uiText("Gate", "门禁").toLower()) {
      actionKey = QStringLiteral("gate");
    } else if (area == uiText("Map", "映射").toLower()) {
      actionKey = QStringLiteral("map");
    } else if (area == uiText("Current SDO", "当前 SDO").toLower()) {
      actionKey = QStringLiteral("currentSdo");
    } else if (area == uiText("Runtime Evidence", "运行证据").toLower()) {
      actionKey = QStringLiteral("runtime");
    } else if (area == uiText("Next", "下一步").toLower()) {
      actionKey = QStringLiteral("next");
    }
  }

  if (actionKey == QStringLiteral("target")) {
    if (topologyTree_) {
      topologyTree_->setFocus();
      if (topologyTree_->currentItem()) {
        topologyTree_->scrollToItem(topologyTree_->currentItem(),
                                    QAbstractItemView::PositionAtCenter);
      }
    }
    logNavigation(uiText("Target", "目标"));
    return;
  }

  if (actionKey == QStringLiteral("gate")) {
    const int blockingRow = firstConsistencyBlockingIssueRow();
    activateWorkspaceTab(consistencyTabIndex_);
    if (blockingRow >= 0) {
      selectAndFocusTableRow(consistencyTable_, blockingRow, 0);
    } else if (!consistencyTable_ || consistencyTable_->rowCount() <= 0) {
      openConsistencyView();
    }
    logNavigation(uiText("Consistency gate", "一致性门禁"));
    return;
  }

  if (actionKey == QStringLiteral("map")) {
    if (hasFailedSdoEvidence()) {
      focusFailedSdoEvidence();
      logNavigation(uiText("Failed OD evidence", "失败 OD 证据"));
      return;
    }
    if (sdoTable_ && selectedPosition() >= 0 &&
        loadedSdoPosition_ == selectedPosition() && sdoTable_->rowCount() > 0) {
      activateObjectDictionaryPaneFor(sdoTable_);
      if (sdoTable_->currentRow() >= 0) {
        selectAndFocusTableRow(sdoTable_, sdoTable_->currentRow(), 1);
      }
      logNavigation(uiText("Object Dictionary", "对象字典"));
      return;
    }
    if (pdoTable_ && selectedPosition() >= 0 &&
        loadedPdoPosition_ == selectedPosition() && pdoTable_->rowCount() > 0) {
      activateWorkspaceTab(pdoMapTabIndex_);
      if (pdoTable_->currentRow() >= 0) {
        selectAndFocusTableRow(pdoTable_, pdoTable_->currentRow(), 2);
      }
      logNavigation(uiText("PDO Map", "PDO 映射"));
      return;
    }
    activateObjectDictionaryPaneFor(sdoTable_);
    logNavigation(uiText("Object Dictionary", "对象字典"));
    return;
  }

  if (actionKey == QStringLiteral("currentSdo")) {
    if (currentSdoWriteDeltaReviewAvailable()) {
      reviewCurrentSdoWriteDelta();
      logNavigation(uiText("Current SDO delta", "当前 SDO 差异"));
      return;
    }
    const int dictionaryRow = currentSdoDictionaryRow();
    activateObjectDictionaryPaneFor(sdoTable_);
    if (dictionaryRow >= 0) {
      selectAndFocusTableRow(sdoTable_, dictionaryRow, 1);
    }
    logNavigation(uiText("Current SDO target", "当前 SDO 目标"));
    return;
  }

  if (actionKey == QStringLiteral("runtime")) {
    if (startupSdoRowsWithWatchDiffs().size() > 0) {
      focusStartupSdoWatchDiffs();
      logNavigation(uiText("Startup diffs", "Startup 偏差"));
      return;
    }
    if (watchTable_ && watchTable_->rowCount() > 0) {
      activateWorkspaceTab(watchTabIndex_);
      const int watchRow = currentSdoWatchRow();
      if (watchRow >= 0) {
        selectAndFocusTableRow(watchTable_, watchRow, 1);
      } else if (watchTable_->currentRow() >= 0) {
        selectAndFocusTableRow(watchTable_, watchTable_->currentRow(), 1);
      }
      logNavigation(uiText("Watch evidence", "Watch 证据"));
      return;
    }
    activateWorkspaceTab(freeRunTabIndex_);
    if (freeRunEntryTable_ && freeRunEntryTable_->currentRow() >= 0) {
      selectAndFocusTableRow(freeRunEntryTable_,
                             freeRunEntryTable_->currentRow(), 0);
    }
    logNavigation(uiText("Free Run evidence", "Free Run 证据"));
    return;
  }

  if (actionKey == QStringLiteral("next")) {
    const int nextStep = nextCommissioningWorkflowStep();
    activateWorkspaceTab(overviewTabIndex_);
    if (nextStep >= 0 && workflowTable_) {
      selectAndFocusTableRow(workflowTable_, nextStep, 2);
    }
    logNavigation(uiText("Workflow next row", "工作流下一行"));
    return;
  }

  if (combined.contains("diagnostic") || combined.contains("诊断")) {
    activateWorkspaceTab(diagnosticsTabIndex_);
    logNavigation(uiText("Diagnostics", "诊断"));
  }
}

void MainWindow::updateNextBestAction() {
  if (!nextBestActionButton_) {
    return;
  }

  NextBestActionInput actionInput;
  actionInput.workflow = commissioningWorkflowInput();
  actionInput.consistencyBlockingIssueRow = firstConsistencyBlockingIssueRow();
  const SlaveEvidenceMatrixPriorityCounts priorityCounts =
      slaveEvidenceMatrixPriorityCounts(slaveEvidenceMatrixTable_);
  actionInput.matrixP0 = priorityCounts.p0;
  actionInput.matrixP1 = priorityCounts.p1;
  actionInput.matrixP2 = priorityCounts.p2;

  if (diagnosticsTable_) {
    for (int row = diagnosticsTable_->rowCount() - 1; row >= 0; --row) {
      const QString level = diagnosticsTable_->item(row, 1)
                                ? diagnosticsTable_->item(row, 1)->text()
                                : QString();
      if (level == "Error") {
        actionInput.hasDiagnosticError = true;
        break;
      }
    }
  }

  const NextBestActionDecision decision = chooseNextBestAction(actionInput);
  const NextBestActionUiState uiState =
      buildNextBestActionUiState(decision, actionInput, nextBestActionTexts());

  nextBestActionButton_->setText(uiState.text);
  nextBestActionButton_->setToolTip(uiState.tip);
  nextBestActionButton_->setStatusTip(uiState.tip);
  nextBestActionButton_->setIcon(
      style()->standardIcon(nextBestActionStandardPixmap(uiState.icon)));
  nextBestActionButton_->setEnabled(uiState.enabled);
  nextBestActionButton_->setProperty("action", uiState.actionKey);
  nextBestActionButton_->setProperty("severity", uiState.severityKey);
  repolish(nextBestActionButton_);
}

void MainWindow::runNextBestAction() {
  if (!nextBestActionButton_) {
    return;
  }

  const QString action = nextBestActionButton_->property("action").toString();
  if (action == nextBestActionKey(NextBestActionKind::Connect)) {
    client_.connectToDaemon();
  } else if (action == nextBestActionKey(NextBestActionKind::Rescan)) {
    client_.rescan();
    requestRefresh();
  } else if (action == nextBestActionKey(NextBestActionKind::SelectSlave)) {
    if (topologyTree_) {
      topologyTree_->setFocus();
      if (!slaves_.isEmpty() && topologyTree_->topLevelItemCount() > 0) {
        auto *master = topologyTree_->topLevelItem(0);
        if (master && master->childCount() > 0) {
          topologyTree_->setCurrentItem(master->child(0));
        }
      }
    }
  } else if (action == nextBestActionKey(NextBestActionKind::LoadOd)) {
    activateObjectDictionaryPaneFor(sdoTable_);
    if (client_.isConnected() && selectedPosition() >= 0) {
      client_.sdos(selectedPosition());
    }
  } else if (action ==
             nextBestActionKey(NextBestActionKind::FailedOdEvidence)) {
    focusFailedSdoEvidence();
  } else if (action == nextBestActionKey(NextBestActionKind::LoadPdo)) {
    activateWorkspaceTab(pdoMapTabIndex_);
    if (client_.isConnected() && selectedPosition() >= 0) {
      client_.pdos(selectedPosition());
    }
  } else if (action == nextBestActionKey(NextBestActionKind::AddWatch)) {
    activateWorkspaceTab(watchTabIndex_);
    if (selectedPosition() >= 0) {
      addCurrentSdoToWatch();
    }
  } else if (action == nextBestActionKey(NextBestActionKind::FreeRun)) {
    activateWorkspaceTab(freeRunTabIndex_);
    if (client_.isConnected() && selectedPosition() >= 0) {
      if (auto *freeRunAction = findChild<QAction *>("freeRunAction")) {
        freeRunAction->trigger();
      } else {
        setFreeRun(!freeRun_);
      }
    }
  } else if (action == nextBestActionKey(NextBestActionKind::Diagnostics)) {
    activateWorkspaceTab(diagnosticsTabIndex_);
  } else if (action == nextBestActionKey(NextBestActionKind::StartupDiffs)) {
    focusStartupSdoWatchDiffs();
  } else if (action ==
             nextBestActionKey(NextBestActionKind::ConsistencyEvidenceIssue)) {
    focusEvidenceFromConsistency(firstConsistencyBlockingIssueRow());
  } else if (action == nextBestActionKey(NextBestActionKind::Consistency)) {
    openConsistencyView();
  } else if (action == nextBestActionKey(NextBestActionKind::MatrixReview)) {
    activateWorkspaceTab(overviewTabIndex_);
    if (slaveEvidenceMatrixScopeFilter_) {
      const int allScope = slaveEvidenceMatrixScopeFilter_->findData("all");
      if (allScope >= 0) {
        slaveEvidenceMatrixScopeFilter_->setCurrentIndex(allScope);
      }
    }
    if (slaveEvidenceMatrixFilter_) {
      slaveEvidenceMatrixFilter_->clear();
    }
    reviewFirstSlaveEvidenceMatrixIssue();
  } else {
    showCommandPalette();
  }

  updateDiagnostics(
      "Info", "Navigator",
      uiText("Next Best Action executed: %1", "已执行下一最佳动作：%1")
          .arg(nextBestActionButton_->text()));
  updateNextBestAction();
}

void MainWindow::filterCommissioningWorkflow() {
  if (!workflowTable_) {
    return;
  }

  const QString needle =
      workflowFilter_ ? workflowFilter_->text().trimmed() : QString();
  const QString scope =
      workflowScopeFilter_
          ? workflowScopeFilter_->currentData().toString()
          : QString::fromLatin1(kCommissioningWorkflowScopeAll);
  const CommissioningWorkflowFilterStats stats =
      filterCommissioningWorkflowTable(workflowTable_, scope, needle,
                                       uiText("None", "无"));

  const int current = workflowTable_->currentRow();
  if (current < 0 || current >= workflowTable_->rowCount() ||
      workflowTable_->isRowHidden(current)) {
    if (stats.firstVisible >= 0) {
      workflowTable_->setCurrentCell(stats.firstVisible,
                                     kCommissioningWorkflowStepColumn);
      workflowTable_->selectRow(stats.firstVisible);
    } else {
      workflowTable_->clearSelection();
    }
  }

  if (workflowSummaryLabel_) {
    const QString scopeLabel = workflowScopeFilter_
                                   ? workflowScopeFilter_->currentText()
                                   : uiText("All", "全部");
    const QString currentDetail = workflowSummaryLabel_->toolTip().trimmed();
    workflowSummaryLabel_->setToolTip(
        uiText("%1\n\nVisible workflow rows: %2/%3\nScope: %4\nOpen: %5 | "
               "Blocked: %6 | Action: %7 | Ready: %8 | Risk: %9 | Evidence "
               "gaps: %10\nFiltering is local only and does not read the bus.",
               "%1\n\n可见工作流行：%2/%3\n范围：%4\n未完成：%5 | 受阻：%6 | "
               "待执行：%7 | 就绪：%8 | 风险：%9 | 证据缺口：%10\n过滤仅在本地"
               "完成，不读取总线。")
            .arg(currentDetail.isEmpty()
                     ? uiText("Commissioning Workflow", "调试工作流")
                     : currentDetail)
            .arg(stats.visible)
            .arg(workflowTable_->rowCount())
            .arg(scopeLabel)
            .arg(stats.open)
            .arg(stats.blocked)
            .arg(stats.action)
            .arg(stats.ready)
            .arg(stats.risk)
            .arg(stats.gaps));
  }
  if (workflowReviewButton_) {
    workflowReviewButton_->setEnabled(stats.hasVisibleIssue);
  }
  if (workflowReviewNextButton_) {
    workflowReviewNextButton_->setEnabled(stats.hasVisibleIssue);
  }
  updateWorkflowStepCopyButton();
  updateWorkflowStepDetail();
}

void MainWindow::reviewFirstCommissioningWorkflowIssue() {
  if (!workflowTable_) {
    return;
  }
  filterCommissioningWorkflow();
  const int row = firstCommissioningWorkflowIssueRow(workflowTable_);
  if (row >= 0) {
    selectAndFocusTableRow(workflowTable_, row, 2);
    updateDiagnostics(
        "Info", "Commissioning Workflow",
        uiText("Selected first visible workflow issue #%1 without running it",
               "已选择首个可见工作流问题 #%1，未执行该步骤")
            .arg(row + 1));
    statusBar()->showMessage(
        uiText("Selected first workflow issue. No bus access was requested.",
               "已选择首个工作流问题；未请求总线访问。"),
        3000);
    return;
  }
  statusBar()->showMessage(uiText("No visible workflow issue to review.",
                                  "当前没有可见工作流问题可审阅。"),
                           3000);
}

void MainWindow::reviewNextCommissioningWorkflowIssue() {
  if (!workflowTable_) {
    return;
  }
  filterCommissioningWorkflow();
  const int rowCount = workflowTable_->rowCount();
  if (rowCount <= 0) {
    statusBar()->showMessage(
        uiText("No workflow issue to review.", "当前没有工作流问题可审阅。"),
        3000);
    return;
  }

  const int row = nextCommissioningWorkflowIssueRow(
      workflowTable_, workflowTable_->currentRow());
  if (row >= 0) {
    selectAndFocusTableRow(workflowTable_, row, 2);
    updateDiagnostics(
        "Info", "Commissioning Workflow",
        uiText("Selected next visible workflow issue #%1 without running it",
               "已选择下一个可见工作流问题 #%1，未执行该步骤")
            .arg(row + 1));
    statusBar()->showMessage(
        uiText("Selected next workflow issue. No bus access was requested.",
               "已选择下个工作流问题；未请求总线访问。"),
        3000);
    return;
  }

  statusBar()->showMessage(uiText("No visible workflow issue to review.",
                                  "当前没有可见工作流问题可审阅。"),
                           3000);
}

bool MainWindow::copyWorkflowStepDigest(int row) {
  if (!workflowTable_ || row < 0 || row >= workflowTable_->rowCount() ||
      workflowTable_->isRowHidden(row)) {
    statusBar()->showMessage(uiText("Select a visible workflow step to copy.",
                                    "请选择一条可见的工作流步骤再复制。"),
                             3000);
    return false;
  }

  QString details;
  for (int column = 0; column < workflowTable_->columnCount(); ++column) {
    if (auto *item = workflowTable_->item(row, column)) {
      details = item->toolTip().trimmed();
      if (!details.isEmpty()) {
        break;
      }
    }
  }

  QStringList lines;
  const CommissioningWorkflowTableRow workflowRow =
      commissioningWorkflowTableRowFromTable(workflowTable_, row);
  lines << uiText("NekoEcat Studio Commissioning Workflow Step",
                  "NekoEcat Studio 调试工作流步骤");
  lines << QString("%1: %2").arg(uiText("Master", "主站"), activeMasterName());
  lines << QString("%1: %2").arg(uiText("Row", "行"), row + 1);
  lines << QString("%1: %2").arg(uiText("Phase", "阶段"), workflowRow.phase);
  lines << QString("%1: %2").arg(uiText("Status", "状态"), workflowRow.status);
  lines << QString("%1: %2").arg(uiText("Step", "步骤"), workflowRow.step);
  lines << QString("%1: %2").arg(uiText("Risk", "风险"), workflowRow.risk);
  lines << QString("%1: %2").arg(uiText("Evidence", "依据"),
                                 workflowRow.evidence);
  lines << QString("%1: %2").arg(uiText("Next Action", "下一步动作"),
                                 workflowRow.nextAction);
  if (auto *runNextButton = findChild<QPushButton *>("overviewRunNext")) {
    lines << QString("%1: %2").arg(
        uiText("Workflow Run Next", "工作流执行下一步"),
        runNextButton->text().trimmed());
  }
  if (nextBestActionButton_) {
    lines << QString("%1: %2").arg(
        uiText("Current Next Best Action", "当前下一最佳动作"),
        nextBestActionButton_->text().trimmed());
  }
  if (workflowSummaryLabel_ &&
      !workflowSummaryLabel_->text().trimmed().isEmpty()) {
    lines << QString("%1: %2").arg(uiText("Workflow Summary", "工作流摘要"),
                                   workflowSummaryLabel_->text().trimmed());
  }
  if (!details.isEmpty()) {
    lines << QString();
    lines << uiText("Step Detail", "步骤详情");
    const QStringList detailLines = details.split('\n', Qt::SkipEmptyParts);
    for (const QString &detail : detailLines) {
      lines << QString("- %1").arg(detail.trimmed());
    }
  }

  lines << QString();
  lines << uiText(
      "Local Action: Copy Step Evidence prepares this workflow row for "
      "handoff or pre-action review.",
      "本地动作：复制步骤证据用于交接或执行前复核该工作流行。");
  lines << uiText("Boundary: clipboard copy only; no bus read, no OD/PDO/ESI "
                  "load, no SDO write, no state change, no Free Run change, "
                  "and no Host Health.",
                  "边界：只复制到剪贴板；不读取总线、不加载 OD/PDO/ESI、不写 "
                  "SDO、不切换状态、不改变 Free Run，也不运行 Host Health。");

  QApplication::clipboard()->setText(lines.join('\n'));
  updateDiagnostics("Info", "Commissioning Workflow",
                    uiText("Copied commissioning workflow step #%1 to "
                           "clipboard",
                           "已复制调试工作流第 %1 步到剪贴板")
                        .arg(row + 1));
  statusBar()->showMessage(
      uiText("Copied workflow step. No bus access was requested.",
             "已复制工作流步骤；未请求总线访问。"),
      3000);
  return true;
}

int MainWindow::nextCommissioningWorkflowStep() const {
  return nextCommissioningWorkflowStepIndex(commissioningWorkflowInput());
}

void MainWindow::runNextCommissioningWorkflowStep() {
  const int row = nextCommissioningWorkflowStep();
  if (row < 0) {
    updateDiagnostics("Info", "Workflow",
                      uiText("Commissioning workflow is already ready",
                             "调试工作流当前已就绪"));
    return;
  }
  runCommissioningWorkflowStep(row);
}

void MainWindow::runCommissioningWorkflowStep(int row) {
  if (!tabs_) {
    return;
  }

  switch (commissioningWorkflowStepForIndex(row)) {
  case CommissioningWorkflowStep::ConnectRuntime:
    if (!client_.isConnected()) {
      client_.connectToDaemon();
    } else {
      requestRefresh();
    }
    break;
  case CommissioningWorkflowStep::ScanTopology:
    if (client_.isConnected()) {
      client_.rescan();
      requestRefresh();
    }
    break;
  case CommissioningWorkflowStep::SelectSlave:
    topologyTree_->setFocus();
    if (topologyTree_->currentItem()) {
      topologyTree_->scrollToItem(topologyTree_->currentItem());
    }
    break;
  case CommissioningWorkflowStep::InspectObjectDictionary:
    activateObjectDictionaryPaneFor(sdoTable_);
    if (client_.isConnected() && selectedPosition() >= 0) {
      client_.sdos(selectedPosition());
    }
    break;
  case CommissioningWorkflowStep::ReviewObjectDictionaryEvidence:
    focusFailedSdoEvidence();
    break;
  case CommissioningWorkflowStep::ReviewPdoMap:
    activateWorkspaceTab(pdoMapTabIndex_);
    if (client_.isConnected() && selectedPosition() >= 0) {
      client_.pdos(selectedPosition());
    }
    break;
  case CommissioningWorkflowStep::MonitorWatch:
    activateWorkspaceTab(watchTabIndex_);
    if (selectedPosition() >= 0) {
      addCurrentSdoToWatch();
    }
    break;
  case CommissioningWorkflowStep::ReviewStartupDiffs:
    focusStartupSdoWatchDiffs();
    break;
  case CommissioningWorkflowStep::RunConsistencyGate: {
    int consistencyErrors = 0;
    int consistencyWarnings = 0;
    consistencyIssueCounts(&consistencyErrors, &consistencyWarnings, nullptr,
                           nullptr);
    const bool hasConsistencyCheck =
        consistencyFresh_ && consistencyCheckAvailable();
    const bool hasConsistencyBlockingIssues = consistencyHasBlockingIssues(
        {consistencyErrors, consistencyWarnings, 0, 0});
    if (hasConsistencyCheck && hasConsistencyBlockingIssues) {
      focusEvidenceFromConsistency(firstConsistencyBlockingIssueRow());
    } else {
      openConsistencyView();
    }
  } break;
  case CommissioningWorkflowStep::ValidateProcessImage:
    activateWorkspaceTab(freeRunTabIndex_);
    if (client_.isConnected() && selectedPosition() >= 0) {
      if (auto *action = findChild<QAction *>("freeRunAction")) {
        action->trigger();
      } else {
        setFreeRun(!freeRun_);
      }
    }
    break;
  }
  updateCommissioningWorkflow();
  updateSelectedDriveSummary();
}

void MainWindow::updateHostHealth(const QJsonArray &checks) {
  if (!hostHealthTable_) {
    return;
  }

  const HostHealthUiState uiState =
      buildHostHealthUiState(checks, hostHealthTexts());
  setTableRows(hostHealthTable_, uiState.headers, uiState.rows);

  for (int row = 0; row < hostHealthTable_->rowCount(); ++row) {
    const QColor color = hostHealthColorForKey(uiState.colorKeys.value(row));
    for (int column = 0; column < hostHealthTable_->columnCount(); ++column) {
      if (auto *item = hostHealthTable_->item(row, column)) {
        item->setForeground(color);
      }
    }
  }
  hostHealthTable_->resizeColumnsToContents();

  if (hostHealthSummaryLabel_) {
    hostHealthSummaryLabel_->setText(uiState.summary);
  }
  updateActionAvailability();
  updateCommissioningWorkflow();
}

void MainWindow::updateDiagnosticsSummary() {
  if (!diagnosticsSummaryLabel_ || !diagnosticsTable_) {
    return;
  }

  QList<DiagnosticsEventRowState> rows;
  rows.reserve(diagnosticsTable_->rowCount());
  for (int row = 0; row < diagnosticsTable_->rowCount(); ++row) {
    const QString level = diagnosticsTable_->item(row, 1)
                              ? diagnosticsTable_->item(row, 1)->text()
                              : QString();
    rows.append({level, !diagnosticsTable_->isRowHidden(row)});
  }
  diagnosticsSummaryLabel_->setText(
      diagnosticsEventSummary(rows, diagnosticsEventTexts()).text);
  updateTabBadges();
}

void MainWindow::styleDiagnosticsRow(int row, const QString &level) {
  if (!diagnosticsTable_ || row < 0 || row >= diagnosticsTable_->rowCount()) {
    return;
  }
  const QColor color =
      diagnosticsEventColorForKey(diagnosticsEventColorKey(level));
  for (int column = 0; column < diagnosticsTable_->columnCount(); ++column) {
    if (auto *item = diagnosticsTable_->item(row, column)) {
      item->setForeground(color);
    }
  }
}

void MainWindow::updateDiagnostics(const QString &level, const QString &source,
                                   const QString &message) {
  if (!diagnosticsTable_->columnCount()) {
    diagnosticsTable_->setColumnCount(4);
    diagnosticsTable_->setHorizontalHeaderLabels(
        diagnosticsEventHeaders(diagnosticsEventTexts()));
  }
  const int row = diagnosticsTable_->rowCount();
  diagnosticsTable_->insertRow(row);
  diagnosticsTable_->setItem(
      row, 0,
      new QTableWidgetItem(QDateTime::currentDateTime().toString("HH:mm:ss")));
  diagnosticsTable_->setItem(row, 1, new QTableWidgetItem(level));
  diagnosticsTable_->setItem(row, 2, new QTableWidgetItem(source));
  diagnosticsTable_->setItem(row, 3, new QTableWidgetItem(message));
  styleDiagnosticsRow(row, level);
  filterDiagnosticsTable();
  diagnosticsTable_->resizeColumnsToContents();
  updateNextBestAction();
}

void MainWindow::updateTabBadges() {
  if (!tabs_) {
    return;
  }

  auto setTab = [this](int index, const QString &text, const QString &tip) {
    if (index >= 0 && index < tabs_->count()) {
      tabs_->setTabText(index, text);
      tabs_->setTabToolTip(index, tip);
    }
  };

  const WorkspaceTabBadgeCounts badgeCounts = workspaceTabBadgeCounts(
      {.watchTable = watchTable_,
       .startupSdoTable = startupSdoTable_,
       .freeRunEntryTable = freeRunEntryTable_,
       .ioVariableTable = ioVariableTable_,
       .consistencyTable = consistencyTable_,
       .stateMachineTable = stateMachineTable_,
       .diagnosticsTable = diagnosticsTable_,
       .slaveEvidenceMatrixTable = slaveEvidenceMatrixTable_});
  const WorkspaceTabBadgeUiState badges =
      buildWorkspaceTabBadgeUiState(badgeCounts, workspaceTabBadgeTexts());

  setTab(overviewTabIndex_, badges.overview.text, badges.overview.tip);
  setTab(watchTabIndex_, badges.watch.text, badges.watch.tip);
  setTab(startupSdoTabIndex_, badges.startupSdo.text, badges.startupSdo.tip);
  setTab(freeRunTabIndex_, badges.freeRun.text, badges.freeRun.tip);
  setTab(ioVariableTabIndex_, badges.ioVariables.text, badges.ioVariables.tip);
  setTab(consistencyTabIndex_, badges.consistency.text, badges.consistency.tip);
  setTab(stateMachineTabIndex_, badges.stateMachine.text,
         badges.stateMachine.tip);
  setTab(diagnosticsTabIndex_, badges.diagnostics.text, badges.diagnostics.tip);
}

void MainWindow::updateStatusBar() {
  if (!statusSummaryLabel_) {
    return;
  }
  statusSummaryLabel_->setText(
      QString("%1: %2 | %3: %4 | %5: %6 | %7: %8")
          .arg(uiText("Runtime", "运行时"))
          .arg(client_.isConnected() ? uiText("connected", "已连接")
                                     : uiText("offline", "离线"))
          .arg(uiText("Master", "主站"))
          .arg(activeMasterName())
          .arg(uiText("Slaves", "从站"))
          .arg(slaves_.size())
          .arg(uiText("Free Run", "自由运行"))
          .arg(freeRun_ ? uiText("On", "开启") : uiText("Off", "关闭")));
  updateWorkspaceBoundary();
  updateNextBestAction();
  updateTabBadges();
  updateSessionBrief();
}

void MainWindow::updateWorkspaceBoundary() {
  if (!workspaceBoundaryLabel_ || !tabs_) {
    return;
  }

  const SlaveEvidenceMatrixPriorityCounts priorityCounts =
      slaveEvidenceMatrixPriorityCounts(slaveEvidenceMatrixTable_);

  const QString workspaceName = tabs_->tabText(tabs_->currentIndex())
                                    .remove(QRegularExpression(R"( !?\d+$)"));
  const WorkspaceBoundaryUiState state = buildWorkspaceBoundaryUiState(
      workspaceBoundaryKindForPage(tabs_->currentWidget()), workspaceName,
      {.matrixP0 = priorityCounts.p0,
       .matrixP1 = priorityCounts.p1,
       .matrixP2 = priorityCounts.p2,
       .matrixP3 = priorityCounts.p3},
      workspaceBoundaryTexts());

  workspaceBoundaryLabel_->setText(state.label);
  workspaceBoundaryLabel_->setToolTip(state.tooltip);
  workspaceBoundaryLabel_->setStatusTip(workspaceBoundaryLabel_->toolTip());
  workspaceBoundaryLabel_->setProperty("severity", state.severityKey);
  repolish(workspaceBoundaryLabel_);
}

void MainWindow::log(const QString &message) {
  logText_->appendPlainText(QString("[%1] %2").arg(
      QDateTime::currentDateTime().toString("HH:mm:ss"), message));
}

int MainWindow::selectedPosition() const {
  auto *item = topologyTree_->currentItem();
  return item ? item->data(0, Qt::UserRole).toInt() : -1;
}

QVector<int> MainWindow::selectedDictionaryRows() const {
  if (!sdoTable_ || selectedPosition() < 0 ||
      loadedSdoPosition_ != selectedPosition()) {
    return {};
  }
  return selectedTableRows(sdoTable_);
}

QVector<int> MainWindow::selectedSdoHistoryRows() const {
  return selectedTableRows(sdoHistoryTable_);
}

QVector<int> MainWindow::selectedStartupSdoRows() const {
  return selectedTableRows(startupSdoTable_, true);
}

bool MainWindow::watchRowHasValue(int row) const {
  return watchTable_ && row >= 0 && row < watchTable_->rowCount() &&
         !watchTable_->isRowHidden(row) && watchTable_->item(row, 4) &&
         !watchTable_->item(row, 4)->text().trimmed().isEmpty();
}

bool MainWindow::selectedWatchRowsHaveValue() const {
  if (!watchTable_) {
    return false;
  }
  for (const int row : selectedTableRows(watchTable_, true)) {
    if (watchRowHasValue(row)) {
      return true;
    }
  }
  return false;
}

void MainWindow::setSelectedSlave(int position) {
  if (position < 0) {
    selectedLabel_->setText(activeMasterName());
    beginSelectedSlaveOnlineLoad(-1);
    filterWatchTable();
    updateSelectedSlavePanel();
    updateActionAvailability();
    updateCommissioningWorkflow();
    updateIoVariableTable();
    updateStateMachineView();
    return;
  }
  for (const auto &slave : slaves_) {
    if (slave.position == position) {
      selectedLabel_->setText(
          QString("#%1  %2").arg(slave.position).arg(slave.name));
      beginSelectedSlaveOnlineLoad(position);
      client_.slaveInfo(position);
      client_.pdos(position);
      client_.sdos(position);
      client_.xml(position);
      filterWatchTable();
      updateSelectedSlavePanel();
      updateActionAvailability();
      updateCommissioningWorkflow();
      updateIoVariableTable();
      updateStateMachineView();
      return;
    }
  }
}

void MainWindow::reportTopologyChanges(const QVector<SlaveInfo> &previous,
                                       const QVector<SlaveInfo> &current) {
  const QVector<TopologyChange> changes =
      detectTopologyChanges(previous, current);
  if (changes.isEmpty()) {
    return;
  }

  for (const auto &change : changes) {
    switch (change.kind) {
    case TopologyChangeKind::Added:
      updateDiagnostics("Warning", "Topology",
                        QString("Slave #%1 added: %2 (%3)")
                            .arg(change.position)
                            .arg(change.current.name, change.current.state));
      break;
    case TopologyChangeKind::NameChanged:
      updateDiagnostics("Warning", "Topology",
                        QString("Slave #%1 identity changed: %2 -> %3")
                            .arg(change.position)
                            .arg(change.previous.name, change.current.name));
      break;
    case TopologyChangeKind::StateChanged: {
      const QString level = change.current.state == "OP" ? "Info" : "Warning";
      updateDiagnostics(level, "Topology",
                        QString("Slave #%1 state changed: %2 -> %3 (%4)")
                            .arg(change.position)
                            .arg(change.previous.state, change.current.state,
                                 change.current.name));
      break;
    }
    case TopologyChangeKind::FlagsChanged:
      updateDiagnostics("Info", "Topology",
                        QString("Slave #%1 flags changed: %2 -> %3")
                            .arg(change.position)
                            .arg(change.previous.flags, change.current.flags));
      break;
    case TopologyChangeKind::Removed:
      updateDiagnostics("Error", "Topology",
                        QString("Slave #%1 removed: %2 (%3)")
                            .arg(change.position)
                            .arg(change.previous.name, change.previous.state));
      break;
    }
  }
  consistencyFresh_ = false;
}

void MainWindow::updateSlaves(const QVector<SlaveInfo> &slaves) {
  const int previous = selectedPosition();
  const QVector<SlaveInfo> previousSlaves = slaves_;
  reportTopologyChanges(previousSlaves, slaves);
  slaves_ = slaves;
  topologyTree_->clear();

  auto *master = new QTreeWidgetItem(
      topologyTree_,
      {activeMasterName(),
       QString("%1 %2").arg(slaves.size()).arg(uiText("slaves", "从站"))});
  master->setData(0, Qt::UserRole, -1);
  master->setExpanded(true);

  for (const auto &slave : slaves) {
    auto *item = new QTreeWidgetItem(
        master,
        {QString("#%1  %2").arg(slave.position).arg(slave.name), slave.state});
    item->setData(0, Qt::UserRole, slave.position);
    if (slave.state == "OP") {
      item->setForeground(1, QColor("#8ff0c8"));
    } else if (slave.state == "PREOP") {
      item->setForeground(1, QColor("#ffd27b"));
    }
  }

  topologyTree_->expandAll();
  setMetricCard(slaveCountLabel_, uiText("Slaves", "从站"),
                QString::number(slaves.size()));
  log(QString("Scan complete: %1 slaves").arg(slaves.size()));
  updateDiagnostics("Info", "Scan",
                    QString("%1 slave(s) detected").arg(slaves.size()));
  updateSelectedSlavePanel();
  updateTopologyBaselineSummary();
  updateActionAvailability();
  updateCommissioningWorkflow();
  updateIoVariableTable();
  updateStateMachineView();
  updateStatusBar();

  if (!slaves.isEmpty()) {
    QTreeWidgetItem *target = master->child(0);
    for (int i = 0; i < master->childCount(); ++i) {
      if (master->child(i)->data(0, Qt::UserRole).toInt() == previous) {
        target = master->child(i);
        break;
      }
    }
    topologyTree_->setCurrentItem(target);
  }
}

void MainWindow::updateMasterSummary(const QString &text) {
  const QString phase = capture(text, R"(^\s*Phase:\s*(.+)$)");
  const QString slaves = capture(text, R"(^\s*Slaves:\s*(.+)$)");
  const QString link = capture(text, R"(^\s*Link:\s*(.+)$)");
  const QString loss = capture(text, R"(^\s*Lost frames:\s*(.+)$)");
  setMetricCard(masterStateLabel_, uiText("Master", "主站"),
                phase.isEmpty() ? uiText("Unknown", "未知") : phase);
  if (!slaves.isEmpty()) {
    setMetricCard(slaveCountLabel_, uiText("Slaves", "从站"), slaves);
  }
  setMetricCard(linkStateLabel_, uiText("Link", "链路"),
                link.isEmpty() ? uiText("Unknown", "未知") : link);
  setMetricCard(lossLabel_, uiText("Frame Loss", "丢帧"),
                loss.isEmpty() ? "0" : loss);

  QList<QStringList> rows;
  const auto lines = text.split('\n');
  for (const auto &line : lines) {
    const auto idx = line.indexOf(':');
    if (idx > 0) {
      rows.append({line.left(idx).trimmed(), line.mid(idx + 1).trimmed()});
    }
  }
  setTableRows(metricTable_, {"Metric", "Value"}, rows);
  updateCommissioningWorkflow();
}

void MainWindow::updateSlaveInfo(const QString &text) {
  QList<QStringList> identity;
  for (const QString &key :
       {"Vendor Id", "Product code", "Revision number", "Serial number",
        "Group", "Order number", "Device name"}) {
    const QString value = capture(
        text,
        QString(R"(^\s*%1:\s*(.+)$)").arg(QRegularExpression::escape(key)));
    if (!value.isEmpty()) {
      identity.append({key, value});
    }
  }
  setTableRows(identityTable_, {"Field", "Value"}, identity);

  QList<QStringList> ports;
  bool inPortTable = false;
  for (const auto &line : text.split('\n')) {
    if (line.startsWith("Port  Type")) {
      inPortTable = true;
      continue;
    }
    if (inPortTable) {
      const auto parts = line.simplified().split(' ');
      if (parts.size() >= 5 && parts.first().at(0).isDigit()) {
        ports.append({parts.value(0), parts.value(1), parts.value(2),
                      parts.value(3), parts.value(4)});
      } else if (!line.trimmed().isEmpty()) {
        inPortTable = false;
      }
    }
  }
  setTableRows(portTable_, {"Port", "Type", "Link", "Loop", "Signal"}, ports);

  QList<QStringList> mailboxes;
  for (const QString &prefix :
       {"Bootstrap", "Standard", "Supported protocols"}) {
    const QString value = capture(
        text,
        QString(R"(^\s*%1\s*(.*)$)").arg(QRegularExpression::escape(prefix)));
    if (!value.isEmpty()) {
      QString cleaned = value;
      cleaned.remove(':');
      mailboxes.append({prefix, cleaned.trimmed()});
    }
  }
  setTableRows(mailboxTable_, {"Mailbox", "Value"}, mailboxes);
  updateCommissioningWorkflow();
  updateStateMachineView();
}

void MainWindow::updatePdoTable(const QString &text) {
  QList<QStringList> rows;
  QString sm;
  QString pdo;
  const QRegularExpression smRe(R"(^SM(\d+):.*DefaultSize\s+(\d+).*)");
  const QRegularExpression pdoRe(
      R"(^\s+(RxPDO|TxPDO)\s+(0x[0-9a-fA-F]+)\s+\"(.+)\")");
  const QRegularExpression entryRe(
      R"(^\s+PDO entry\s+(0x[0-9a-fA-F]+):([0-9a-fA-F]+),\s+(\d+)\s+bit,\s+\"(.+)\")");
  for (const auto &line : text.split('\n')) {
    auto m = smRe.match(line);
    if (m.hasMatch()) {
      sm = QString("SM%1 (%2 bytes)").arg(m.captured(1), m.captured(2));
      continue;
    }
    m = pdoRe.match(line);
    if (m.hasMatch()) {
      pdo =
          QString("%1 %2 %3").arg(m.captured(1), m.captured(2), m.captured(3));
      continue;
    }
    m = entryRe.match(line);
    if (m.hasMatch()) {
      rows.append({sm, pdo, m.captured(1), m.captured(2), m.captured(3),
                   m.captured(4)});
    }
  }
  setTableRows(pdoTable_, {"SM", "PDO", "Index", "Sub", "Bits", "Name"}, rows);
  filterPdoTable();
  updateIoVariableTable();
  updateStateMachineView();
}

void MainWindow::filterPdoTable() {
  if (!pdoTable_) {
    return;
  }
  const QString needle = pdoFilter_ ? pdoFilter_->text().trimmed() : QString();
  int visible = 0;
  for (int row = 0; row < pdoTable_->rowCount(); ++row) {
    bool match = needle.isEmpty();
    for (int column = 0; column < pdoTable_->columnCount() && !match;
         ++column) {
      const auto *item = pdoTable_->item(row, column);
      match = item && item->text().contains(needle, Qt::CaseInsensitive);
    }
    pdoTable_->setRowHidden(row, !match);
    if (match) {
      ++visible;
    }
  }
  if (pdoSummaryLabel_) {
    const int total = pdoTable_->rowCount();
    pdoSummaryLabel_->setText(
        total > 0 ? uiText("%1/%2 PDO entries", "%1/%2 个 PDO 条目")
                        .arg(visible)
                        .arg(total)
                  : uiText("No PDO entries", "暂无 PDO 条目"));
  }
  updatePdoRowDetail();
  updateActionAvailability();
  updateCommissioningWorkflow();
}

